import{_ as e,o as a,c as t,a3 as r}from"./chunks/framework.DdpBa4_E.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/98-为了防止阶层的固定化？.md","filePath":"books/xialiu-shehui/98-为了防止阶层的固定化？.md","lastUpdated":1794732511000}'),_={name:"books/xialiu-shehui/98-为了防止阶层的固定化？.md"};function o(s,p,i,n,l,c){return a(),t("div",null,[...p[0]||(p[0]=[r('<h2 id="为了防止阶层的固定化" tabindex="-1">为了防止阶层的固定化？ <a class="header-anchor" href="#为了防止阶层的固定化" aria-label="Permalink to &quot;为了防止阶层的固定化？&quot;">​</a></h2><p>但是，那些人应该也不希望阶层差距被固定化吧？他们不会认为父母“下流”孩子也只能“下流”的社会是理想的社会。因此下流社会应该以“机会恶平等”作为整个社会的基本方针，也就是收入越低的人，越能享受到各种各样的优惠待遇。</p><p>到目前为止日本仍是一个“结果恶平等”的社会，不管努力与否，也不管有没有能力，在薪水方面几乎没有太大的差距。</p><p>在笔者二十多岁成为工薪阶层的一员的时候，工作速度比周围的人快许多，所以很少加班，薪水也拿得少。笔者25岁时每个月大概能拿到25万日元，可能力差、工作速度慢的人却能拿到将近40万日元。由于工作效率高，笔者逐渐承担起更多的职责，28岁那年当上了杂志总编。本来科长或是部长应该做的工作交给了一个28岁的普通员工，但薪水仍然与普通员工一样，甚至比工作速度慢、加班费多的年轻职员还拿得少。</p><p>这就是由“结果恶平等”造成的“结果逆差”现象。</p><p>这种现象是不合理的，应该实行“结果不平等”的成果分配方式，来达到结果上的平等，近十五年来颇为盛行的成果主义风潮正是在这样的背景下掀起的。但是，如果彻底实行成果主义，收入差距只会更加扩大，长此以往阶层的差距会变得固定化，也就不可能实现真正的机会平等。</p><p>比较典型的是教育的机会，上流阶层可以接受良好的教育，但下流阶层却无此可能。如果父母是上流阶层的话，孩子也很容易就能成为上流阶层，反之亦然。</p><p>为了防止阶层差距的固定化，有什么事情是必须要做的呢？那就是更加彻底地实现机会均等。</p><p>完全的机会均等，就是消除由父母的财力、职业、地域等孩子自己无法选择的外在环境的差别所造成的一切不平等。就算父母很贫穷，没有很高的学历，从事的又是地位很低的职业，也即便教育观念不正确，缺乏活力，住在大多数人都是低阶层同类人的地方，但只要孩子有能力，再怎么高等的教育都应该让他接受，再怎么高位的职业也都可以让他去从事。在机会完全均等的社会里，不存在因为阶层不同而产生的不平等现象。</p><p>但是，这种机会完全均等的论调里也包含着难以解决的问题。也就是说，如果机会完全均等的社会一旦成为现实，那么结果的差别就将完全归因于个人的能力，这样的社会不是过于残酷了吗？</p><p>你的成绩不好，不是因为父母贫穷、学历低，而是因为你的脑子不好使，你本身的性格当中就没有学习或工作的欲望，除此之外找不到任何借口，追根究底，甚至有可能将原因归咎于因遗传因子不好而头脑不灵、缺乏活力。这种过分强调优生的思想是非常危险的。近年来电视节目中兴起的“头脑热”“IQ热”并非不能说成是裹了糖衣的优生思想。</p><p>所以，机会均等固然重要，但相比之下更应当首先去做的也许是“机会恶平等”。</p><p>具体来说，可以分为以下五个方面。</p><p>（1）“穿靴式”入学考试</p><p>父母所属阶层低的孩子，有学习能力低下的倾向，如果那不是因为遗传，而是由于家庭环境造成的，那么在大学入学考试时，最好能将低收入家庭子女的合格分数线适当降下来，这就是所谓“穿靴式”的入学考试方法，即将他垫得高一点，助其一臂之力（当然也可以把高收入家庭子女的合格分数线适当提高）。</p><p>这种针对低收入者的“穿靴式”入学考试方式，首先在大谈特谈阶层差距的扩大、固定化问题的佐藤俊树、苅谷刚彦还有橘木俊诏等诸位先生任教的东京大学和京都大学实施如何？如果实在做不到的话，就应该像漫画《龙樱》里描写的那样，将更多具备教学能力的优秀教师选送到素质较差的中学里去。</p><p>（2）东京大学实行学费免除</p><p>近年来国立大学的学费逐渐上涨。笔者读大学的时候，学费从每年2万5千日元涨到5万日元，就引起了民众的骚动，但如今的学费已经涨到了50万日元以上。国立大学理应以培养对国家有用的人才为己任，可现在为什么会专门打学费的主意、越收越高？笔者对此完全不能苟同。</p><p>如果无法将所有国立大学的学费降到原来的水平，那也可以仅限于在公认的一流国立大学实行学费全免制度，或是低收费制度。换句话说，就是从东京大学或京都大学开始实行学费全免。</p><p>如果那样做的话，放弃进入一流大学的下流家庭的孩子，还有地方上犹豫着是否要去东京的孩子，就都能得到努力学习的机会。再加上实行“穿靴式”的入学考试，这部分孩子进入一流大学学习的机会还可能会更多。</p><p>一旦考试合格，接下来就要靠本人的努力了。如果好好用功的话，可以进入大企业或中央政府机构工作，还有机会成为医生、税务师或者会计师，交友圈子也会扩大，因而阶层上升的机会大为提高。所以我们应当优先向下流阶层的人提供这样的机会。</p><p>当然，免除所有大学的全部教育费用是最理想的，除此以外，还可以考虑对低收入家庭用于课外补习的费用实行征税减免。</p><p>如果学费过高，年轻人考入大学后离开父母独立生活也会变得困难，结果就造成“寄生族”不断增加，使年轻人在精神上和经济上都无法自立。因此，免除学费也将有助于年轻人自立。</p><p>（3）大学教育互联网化</p><p>一流大学的课程全部通过互联网进行播送，无论在世界哪个角落都能够接收。对于居住在偏远地方的人来说，进入集中在东京的一流大学就读，生活费是相当高的，为此有人不得不放弃升学的念头。实施了互联网教学后，即便学费较高，但不需要再额外支付高昂的生活费用，对于贫困地区的贫困家庭来说无疑是个好消息。互联网教学还有助于发掘地方上有用的人才，这对整个社会也是意义非凡的。</p><p>（4）从地方到东京求学的资金援助</p><p>即使普及了互联网教学，但从提升个人阶层的角度来说，还是在东京生活和交友较为有利。因此，不少人迫切希望获得在东京生活的资金援助。</p><p>为此，可以考虑由地方政府出资，选拔优秀的、有进取心的人才，补助他们来东京读书和生活的资金。如第八章里提到的那样，从地方小城镇到东京来的年轻人不断增加，不仅有利于增强都市的活力，还有利于促进日本经济与文化的活力。</p><p>如果从地方政府的立场来看认为无甚益处的话，也可以尝试制定另一种制度，即先让学生自费在东京读完大学，毕业之后如果回到地方工作，再支付他们所花费的学费。</p><p>（5）上流阶层要尽“高贵者的义务”</p><p>在对下流阶层提供“恶平等”机会支援的同时，应当让上流阶层承担与其收入和地位相匹配的义务。最近几年的税制改革对高收入者给予了优惠待遇，尽管他们无须向社会缴纳更多的税金，但以捐赠等其他形式将一部分财富回报给社会应当成为一种共识。</p><p>日本经济团体联合会从上世纪90年代开始，就开展了所谓“1%俱乐部”的活动，加盟企业须将利润的1%用于社会公益。与此相类似的，必须在全社会提倡这样一种社会风气：收入达到1000万日元的人捐赠1%，收入3000万日元的人捐赠5%，收入1亿日元的人捐赠10%。对于上流阶层来说，这既是一种高贵的义务，又能提高自己在社会上的名声。</p><p>对于出钱的一方来说，与其缴纳那些不知道用到哪里去的税金，还不如采用捐赠的方式将财富贡献给社会，因为捐赠是透明化的，捐赠者可以清楚地知道自己的财富捐给了什么样的团体或个人，开展了什么样的公益活动等。是捐赠给从事环境研究活动的团体，还是捐赠给高龄者支援团体用于高龄护理活动？或者是捐赠给相关的自由打工族对策机构进行青少年教育活动？这不仅能够体现出捐赠者的个性，同时也能够因为得到了社会的承认而产生满足感。</p><p>本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',34)])])}const u=e(_,[["render",o]]);export{d as __pageData,u as default};
